import {draftSynergyMarkup} from './draft-synergy-ui.js?v=345ebe2e4f45';
import {draftMetaView,META_ROLES} from './draft-meta.js?v=345ebe2e4f45';
import {draftAdvice} from './draft-advice.js?v=345ebe2e4f45';
import {draftConfirmMarkup} from './draft-confirm.js?v=345ebe2e4f45';
export function draftMetaMarkup(c,d,m){
 const {data,state:s,ui,E,esc,img,btn}=c;
 const view=draftMetaView(data,{date:s.date,competition:m.competition,phase:m.phase??s.phase?.key,patch:d.patch,mode:ui.draftMetaMode??'event'});if(!view)return '';
 const open=!!ui.draftMetaOpen,role=ui.draftMetaRole??'all',turn=E.draftTurn(d),human=turn?.team===s.myTeam&&!ui.draftBusy;
 const lanes=role==='all'?META_ROLES:[role],limit=role==='all'?4:12,ours=d.blue===s.myTeam?'blue':'red',other=ours==='blue'?'red':'blue',kind=turn?.kind??'pick';
 const laneMarkup=r=>{
  const unavailable=id=>E.draftUnavailableReason(s,d,id),team=kind==='ban'?d[other]:s.myTeam,player=s.players[s.teams[team].lineup[r]];
  const rows=draftAdvice(view,r,{champions:data.champions,available:id=>!unavailable(id),limit,kind,set:d.set,player:player?.name,mastery:id=>E.mastery(s,player?.id,id),allies:d.picks[ours].map(p=>p.champion),opponents:d.picks[other].map(p=>p.champion)});
  const spent=view.roles[r].map(ch=>({...ch,unavailable:unavailable(ch.id)})).filter(ch=>ch.unavailable);
  const card=ch=>`<div class="meta-choice ${ui.hoverChampion===ch.id&&ui.draftSelectionOrigin==='meta-'+r?'is-selected':''}"><button class="meta-champion ${ch.priority==='OP'?'is-op':''} ${ch.unavailable?'is-unavailable':''}" data-action="draft-pick" data-draft-origin="meta-${r}" data-id="${ch.id}" data-meta-champion="${ch.id}" ${!human||ch.unavailable?'disabled':''} title="${esc(ch.name+' · '+ch.observedRoles.join('/')+' · '+(ch.unavailable||ch.advice?.reasons.join(' / ')||'동일 대회 관측 우선도'))}">${img(ch.id)}<span class="meta-champ-text"><strong>${esc(ch.name)} <b>${ch.priority}</b>${ch.flex?'<i>FLEX</i>':''}</strong><small>${ch.estimated?'해당 라인 픽 기록 없음 · 숙련도 참고':`${view.priorityPatch?'적용 패치':'대회'} 1세트 P/B ${ch.presence===null?'—':Math.round(ch.presence*100)+'%'} · 대회 ${ch.picks}픽${ch.wins===null?'':` ${ch.wins}승`}`}</small>${ch.advice&&!view.allSeason?`<small class="meta-advice" title="${esc(ch.advice.reasons.join(' · '))}">${kind==='ban'?'밴':'픽'} 참고 ${ch.advice.score}점 · ${kind==='ban'?'상대':'우리'} 숙련 ${ch.advice.mastery}</small>`:''}${ch.unavailable?`<em>${esc(ch.unavailable)}</em>`:''}</span></button>${draftConfirmMarkup(c,d,ch.id,'meta-'+r)}</div>`;
  return `<section class="meta-lane" data-meta-lane="${r}"><h3>${r}<small>${esc(E.ROLE_NAMES[r])}</small></h3><div class="meta-champions">${rows.length?rows.map(card).join(''):'<p class="meta-empty">선택 가능한 챔피언이 없습니다.</p>'}</div>${!ui.draftMetaAvailable&&spent.length?`<details class="meta-used-list"><summary>소진·밴·선택 ${spent.length}종</summary>${spent.map(card).join('')}</details>`:''}</section>`;
 };
 const evidence=view.allSeason?`2026 전체 ${view.games}세트 · P/B는 밴이 확인된 1세트 ${view.openingGames}경기 기준`:view.empty?`${view.mode==='prior'?'게임 날짜 이전 ':''}해당 대회의 확인된 기록이 없습니다. 다른 대회 기록은 섞지 않습니다.`:`${view.mode==='prior'?'게임 날짜 이전 ':''}동일 대회 전체 ${view.games}세트 · 현재 패치 ${view.patchGames}세트 · ${view.firstDate.slice(5,10)}~${view.lastDate.slice(5,10)}${view.banGames<view.games?` · 밴이 확인된 ${view.banGames}세트로 P/B 산출`:''} · 다른 대회 자료 제외${view.mode==='event'?' · 진행일 이후 기록을 포함한 회고 참고':''}`;
 return `<section class="draft-meta-panel" aria-label="대회별 포지션 메타"><header><div><span>2026 ${view.allSeason?'전체 시즌':'대회별'} ${kind==='ban'?'밴':'픽'} 추천</span><h2>${esc(view.label)} <small>PATCH ${esc(E.patchLabel(d.patch))}</small></h2></div>${btn(open?'메타 접기':'OP·주요 픽 보기','draft-meta-toggle','aria-expanded="'+open+'"','compact ghost')}</header>${open?`<div class="meta-controls"><div class="meta-modes">${btn(view.allSeason?'2026 전체 기록':'대회 전체 기록','draft-meta-mode','data-id="event" aria-pressed="'+((ui.draftMetaMode??'event')==='event')+'"',(ui.draftMetaMode??'event')==='event'?'compact primary':'compact')}${view.allSeason?'':btn('현재 시점 참고','draft-meta-mode','data-id="prior" aria-pressed="'+(ui.draftMetaMode==='prior')+'"',ui.draftMetaMode==='prior'?'compact primary':'compact')}</div><div class="meta-roles">${['all',...META_ROLES].map(r=>btn(r==='all'?'전 라인':r,'draft-meta-role',`data-id="${r}" aria-pressed="${role===r}"`,role===r?'compact active':'compact')).join('')}</div>${btn(ui.draftMetaAvailable?'선택 가능만 ✓':'선택 가능만','draft-meta-available',`aria-pressed="${!!ui.draftMetaAvailable}"`,'compact ghost')}</div><p class="meta-evidence">${esc(evidence)}</p>${view.customRounds?'<p class="meta-footnote">게임은 아시안게임 없이 3~5R를 진행합니다. 확인된 실전 자료는 2026 정규 3·4R이며, 실제 5R 기록은 없습니다.</p>':''}<div class="meta-lanes ${role!=='all'?'single-lane':''}">${lanes.map(laneMarkup).join('')}</div><p class="meta-footnote">${view.allSeason?'2026 시즌 전체의 픽·밴·승·동반 조합을 집계합니다.':'동일 대회의 모든 세트에서 픽·승·세트 순서·동반 조합·같은 라인 맞대결을 집계하고 선수 숙련도를 함께 반영합니다.'} 참고 점수는 승률이 아닙니다. OP는 ${view.priorityPatch?'적용 패치':'해당 대회'} 1세트 10경기 이상·P/B 65% 이상 기준입니다. 소진 시 다음 후보로 자동 보충하며 미관측 대체 픽을 구분합니다. 라인은 배치 제안이며 최종 포지션은 밴픽 종료 후 자유롭게 정합니다.</p>`:''}</section>${draftSynergyMarkup(c,d,view)}`;
}
